const b = ($json && $json.body) ? $json.body : $json;
const allowed = ['pl', 'en', 'de'];
const lang = allowed.includes(b.lang) ? b.lang : 'pl';
const sig = "<br><br>Zespół AEJaCA<br>Artisan Elegance Jewelry and Crafted Art<br>www.aejaca.com | contact@aejaca.com";
const bodies = {
  pl: "Dzień dobry,<br><br>dziękujemy za kontakt z AEJaCA. Otrzymaliśmy Twoją wiadomość i zajmiemy się nią najszybciej, jak to będzie możliwe (zwykle w ciągu 1-2 dni roboczych).<br><br>W międzyczasie zapraszamy do obejrzenia naszych realizacji na www.aejaca.com. Do usłyszenia.",
  en: "Hello,<br><br>thank you for contacting AEJaCA. We have received your message and will get back to you as soon as possible, usually within 1-2 business days.<br><br>In the meantime, feel free to explore our work at www.aejaca.com. Talk soon.",
  de: "Guten Tag,<br><br>vielen Dank für Ihre Nachricht an AEJaCA. Wir haben Ihre Anfrage erhalten und melden uns so schnell wie möglich, in der Regel innerhalb von 1-2 Werktagen.<br><br>In der Zwischenzeit laden wir Sie ein, unsere Arbeiten auf www.aejaca.com zu entdecken. Bis bald."
};
const html = "<div style='font-family:Georgia,serif;font-size:15px;color:#2b2b2b;line-height:1.65'>" + bodies[lang] + sig + "</div>";
return { to: b.to || '', messageId: b.gmail_message_id || '', lang, html };
